#include "pcm_common.h"
#include "audio/prepared-pcm-cache.h"
#include <vector>
namespace Audio{uint64 verifiedCount=0,hitCount=0,missCount=0,idleCount=0;}
static uint32 seed=0x98137641;static uint32 rng(){seed=seed*1664525+1013904223;return seed;}
struct Ch:PCMChannel_Base{bool playing=false;bool isPlaying()const override{return playing;}void stopInternal()override{playing=false;}void start(const std::vector<int8>&d,bool loop){clear();setData(d.data(),d.size()<<11,0,true);setupLoop(loop?d.size()/3:d.size(),loop?d.size()-d.size()/3:0);setRate((rng()%65000)+1);setVolume(rng()%256);setPanPos(rng()%256);playing=true;activate();}void emptyLoop(){setupLoop(0,0);}void stoppedActive(){playing=false;activate();}void silentPlaying(){playing=true;deactivate();}void change(){setVolume(rng()%256);setPanPos(rng()%256);setRate((rng()%65000)+1);}};
int main(){for(int trial=0;trial<1000;trial++){PCMDevice_Base dev((trial%3==0)?19300:((trial%3==1)?22050:44100),(trial%3==0)?57:((trial%3==1)?128:255),8);Ch ch[8];for(int i=0;i<8;i++)dev.assignChannel(i,&ch[i]);std::vector<int8>d(1+rng()%256);for(auto &v:d)v=(int8)rng();ch[0].start(d,trial%3!=0);for(int voice=1;voice<(trial%9);voice++)ch[voice].start(d,true);for(int block=0;block<40;block++){if(block==1&&trial%10==0)ch[0].emptyLoop();if(block==5&&trial%4==0)ch[0].stoppedActive();if(block==15&&trial%4==1)ch[0].silentPlaying();if(block%7==0)ch[0].change();if(block%9==0)d[rng()%d.size()]=(int8)rng();dev.setMusicVolume(rng()%257);dev.setSfxVolume(rng()%257);dev.setSfxChanMask(rng()%256);std::vector<int32>b((1+rng()%511)*2);for(auto &v:b)v=(int32)(rng()%200001)-100000;dev.readBuffer(b.data(),b.size()/2);}}
printf("PORTABLE_PASS hits=%llu misses=%llu verified=%llu idle=%llu\n",(unsigned long long)Audio::hitCount,(unsigned long long)Audio::missCount,(unsigned long long)Audio::verifiedCount,(unsigned long long)Audio::idleCount);return Audio::verifiedCount>10000&&Audio::missCount>100&&(!Audio::PreparedPCMCache().valueMode()||Audio::idleCount>1000)?0:1;}
